/**
 * Product Finder — Shared types for DST search and import.
 */

// ============================================================================
// DST API Response Types (raw shapes from supplier)
// ============================================================================

/** DST ProductInfo — raw shape from the Spring Data backend. Each item in data.content[]. */
export interface DstProductRaw {
  id: string
  data: DstDataNode
  createdAt: string
  updatedAt: string
}

/** Nested payload inside each DST product result */
export interface DstDataNode {
  country: string[]
  currency: string
  language: string
  identifiers: {
    ean_upc?: string
    gln?: string
    supplier: string
    itemnumber: string
    supplier_description: string
  }
  orderinformation: {
    status: string
    ordercode: string
    orderamount: number
    units_in_packaging?: number
    minimum_orderamount: number
    status_description: string
  }
  productinformation: {
    descriptions?: {
      receipt_text: string
      long_description: string
      short_description: string
    }
    price_information: {
      vat: string
      gross_purchase_price: number
      recommended_retailprice: number
      vat_description: string
    }
    physical_specifications?: { net_weight: number; gross_weight: number }
    general_productinformation: {
      brand: string
      model: string
      pos_image: string[]
      itemnumber_producer: string
      brand_description: string
    }
  }
  productclassification: {
    keyword: string
    keyword_description: string
    profiles: string[]
    productgroup: string
    productgroup_description: string
  }
}

/** A single deduplicated offer — what the client sees */
export interface DstOfferRaw {
  eanUpc: string
  itemNumber: string
  brand?: string
  model?: string
  name?: string
  imageUrl?: string
  recommendedRetailPriceGross?: number
  grossPurchasePriceGross?: number
  suggestedSellPriceNet?: number
  suggestedCostPriceNet?: number
  supplierName: string
  lang?: string
}

/** DST paginated response — Spring Data Page<T> shape */
export interface DstPagedResponse {
  content: unknown[]
  pageable: { pageNumber: number; pageSize: number }
  totalPages: number
  totalElements: number
  first: boolean
  last: boolean
  numberOfElements: number
  sort?: unknown
  number: number
  size: number
  empty: boolean
}

// ============================================================================
// Deduplicated Supplier Offer (what the client sees)
// ============================================================================

/** A single deduplicated supplier product offer */
export interface SupplierOffer {
  /** EAN/UPC barcode */
  eanUpc: string
  /** Supplier's internal item number */
  itemNumber: string
  /** Brand name */
  brand?: string
  /** Model / product line */
  model?: string
  /** Product name (Dutch preferred) */
  name?: string
  /** Product image URL (first available) */
  imageUrl?: string
  /** Recommended retail price in EUR gross */
  recommendedRetailPriceGross?: number
  /** Gross purchase price in EUR */
  grossPurchasePriceGross?: number
  /** Suggested net sell price (gross / 1.21) */
  suggestedSellPriceNet?: number
  /** Suggested net cost price (gross / 1.21) */
  suggestedCostPriceNet?: number
  /** Supplier name */
  supplierName: string
  /** Language code of the selected variant */
  lang?: string
}

// ============================================================================
// Search Request / Response Types
// ============================================================================

/** Query parameters for EAN search */
export interface EanSearchParams {
  ean: string
}

/** Query parameters for keyword search */
export interface KeywordSearchParams {
  q: string
  page?: number
  size?: number
}

/** Unified search result envelope */
export interface SearchResults {
  offers: SupplierOffer[]
  /** Present only for keyword (paginated) searches */
  pagination?: {
    page: number
    pageSize: number
    totalPages: number
    totalElements: number
  }
}

// ============================================================================
// Import Types
// ============================================================================

/** Request body for importing a product into the local catalog */
export interface ImportRequest {
  /** EAN/UPC barcode (must match a cached supplier_product) */
  eanUpc: string
  /** Product name (editable from DST default) */
  name: string
  /** Net sell price in cents (editable from DST suggested) */
  sellPrice: number
  /** Net cost price in cents (editable from DST suggested) */
  costPrice: number
  /** Supplier name (must match a cached supplier_product) */
  supplierName: string
  /** Initial stock quantity — defaults to 0 if not provided */
  quantityOnHand?: number
}

/** Response after importing a product */
export interface ImportResult {
  success: boolean
  partId?: string
  action: 'created' | 'updated'
  message: string
}
